int main(int n,char**v){if(n!=3)return 1;if(!strcmp(v[1],"write")){SDL_Surface*s=SDL_CreateSurface(432,544,SDL_PIXELFORMAT_RGBA32);if(!s)return 2;for(int y=0;y<s->h;y++)for(int x=0;x<s->w;x++){unsigned char*p=(unsigned char*)s->pixels+y*s->pitch+x*4;p[0]=32+180*x/(s->w-1);p[1]=64+120*y/(s->h-1);p[2]=32;p[3]=255;}int ok=SDL_SavePNG(s,v[2]);SDL_DestroySurface(s);return ok?0:3;}FILE*f=fopen(v[2],"rb");int w,h,max;if(!f||fscanf(f,"P6 %d %d %d",&w,&h,&max)!=3||w!=1280||h!=960||max!=255||fgetc(f)!='\n')return 4;unsigned char*p=malloc((size_t)w*h*3);if(!p||fread(p,3,(size_t)w*h,f)!=(size_t)w*h)return 5;fclose(f);const int xs[]={72*4+2,136*4+2,183*4+1,247*4+1};for(int i=0;i<4;i++){float x=xs[i]/4.f,u=i<2?x-52:267-x;int expected[]={ (int)((32+180*u/108)*127/128), (int)((64+120*(80.5f-24)/136)*127/128),32};unsigned char*q=p+((size_t)(80*4+2)*w+xs[i])*3;for(int c=0;c<3;c++)if(abs(q[c]-expected[c])>6){fprintf(stderr,"Mirror sample x=%d c=%d: %u expected~%d\n",xs[i],c,q[c],expected[c]);return 6;}}for(int i=0;i<2;i++){int x=i?268:51;unsigned char*q=p+((size_t)(80*4)*w+x*4)*3;if(q[0]||q[1]||q[2])return 7;}free(p);puts("8-bit UI sprite and reflected quad preserve source orientation and bounds");return 0;}
